<div class="admin-columns"><section><div class="page-actions"><h2>Comunas</h2><button class="btn btn-primary btn-sm" data-modal-open="communeModal">+ Comuna</button></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Comuna</th><th>Región</th><th>Usuarios</th><th>Sectores</th></tr></thead><tbody><?php foreach($communes as $commune):?><tr><td><strong><?= e($commune['name']) ?></strong></td><td><?= e($commune['region']) ?></td><td><?= $commune['users_count'] ?></td><td><?= $commune['sectors_count'] ?></td></tr><?php endforeach;?></tbody></table></div></div></section><section><div class="page-actions"><h2>Sectores</h2><button class="btn btn-outline-primary btn-sm" data-modal-open="sectorModal">+ Sector</button></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Sector</th><th>Comuna</th><th>Estado</th></tr></thead><tbody><?php foreach($sectors as $sector):?><tr><td><strong><?= e($sector['name']) ?></strong></td><td><?= e($sector['commune_name']) ?></td><td><?= e($sector['status']) ?></td></tr><?php endforeach;?></tbody></table></div></div></section></div>
